# Initially generated by GitHub Copilot.
import json
import unittest

from author import mam_parsed_docs_build
from author_util import claim as claim_mod
from verify_mp import payload_examples
from verify_mp.corpus import Context, Corpus, PlainCorpus


def _make_record(*, claim_id: str, payload, subject: str = "mp:plus"):
    return claim_mod.make_record(
        claim_id,
        payload=payload,
        kind="example",
        subject=subject,
    )


def _ctx(*, plus_files=None, plain_files=None):
    return Context(
        corpus=Corpus(files=[] if plus_files is None else plus_files, book39s=[]),
        corpus_plain=PlainCorpus(files=[] if plain_files is None else plain_files),
        survey={},
        survey_plain={},
    )


class TestVerifyMpPayloadExamples(unittest.TestCase):
    def test_normalize_payload_parses_strict_json_object(self):
        record = _make_record(
            claim_id="mp.plus.example.strict-json",
            payload='  {"k": [1, 2, 3]}  ',
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertEqual(normalized, {"k": [1, 2, 3]})

    def test_normalize_payload_keeps_non_json_string_unchanged(self):
        payload = '"header": {"book24_name": "ספר איוב"}'
        record = _make_record(
            claim_id="mp.plus.example.non-json-fragment",
            payload=payload,
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertEqual(normalized, payload)

    def test_normalize_payload_non_string_passthrough(self):
        payload = {"already": "parsed"}
        record = _make_record(
            claim_id="mp.plus.example.non-string",
            payload=payload,
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertIs(normalized, payload)

    def test_normalize_payload_rejects_legacy_trailing_comma(self):
        record = _make_record(
            claim_id="mp.plus.example.trailing-comma",
            payload='{"a": 1,}',
        )

        with self.assertRaisesRegex(AssertionError, r"payload must be strict JSON"):
            payload_examples._normalize_payload(record)

    def test_match_pattern_any_value_token(self):
        self.assertTrue(
            payload_examples._match_pattern(payload_examples._ANY_VALUE_TOKEN, {"x": 1})
        )
        self.assertTrue(
            payload_examples._match_pattern(payload_examples._ANY_VALUE_TOKEN, "abc")
        )

    def test_match_pattern_any_dict_marker(self):
        expected = {payload_examples._ANY_DICT_MARKER_KEY: True}

        self.assertTrue(payload_examples._match_pattern(expected, {"k": "v"}))
        self.assertFalse(
            payload_examples._match_pattern(expected, ["not", "a", "dict"])
        )

    def test_match_pattern_any_list_marker(self):
        expected = {payload_examples._ANY_LIST_MARKER_KEY: True}

        self.assertTrue(payload_examples._match_pattern(expected, ["x"]))
        self.assertFalse(payload_examples._match_pattern(expected, {"not": "a list"}))

    def test_match_pattern_empty_list_is_literal_empty(self):
        self.assertTrue(payload_examples._match_pattern([], []))
        self.assertFalse(payload_examples._match_pattern([], [1]))

    def test_match_pattern_empty_object_is_literal_empty(self):
        self.assertTrue(payload_examples._match_pattern({}, {}))
        self.assertFalse(payload_examples._match_pattern({}, {"x": 1}))

    def test_match_pattern_nonempty_object_requires_exact_keys(self):
        expected = {"a": 1}

        self.assertTrue(payload_examples._match_pattern(expected, {"a": 1}))
        self.assertFalse(payload_examples._match_pattern(expected, {"a": 1, "b": 2}))

    def test_match_pattern_list_gap_token(self):
        expected = ["start", payload_examples._LIST_GAP_TOKEN, "end"]

        self.assertTrue(
            payload_examples._match_pattern(expected, ["start", "mid", "end"])
        )
        self.assertTrue(
            payload_examples._match_pattern(expected, ["start", "m1", "m2", "end"])
        )
        self.assertFalse(payload_examples._match_pattern(expected, ["start", "mid"]))

    def test_match_pattern_any_string_true(self):
        expected = {payload_examples._ANY_STRING_TOKEN: True}

        self.assertTrue(payload_examples._match_pattern(expected, "abc"))
        self.assertFalse(payload_examples._match_pattern(expected, 123))

    def test_match_pattern_any_string_with_mid_gap(self):
        expected = {
            payload_examples._ANY_STRING_TOKEN: [
                "prefix",
                payload_examples._MID_STRING_GAP_TOKEN,
                "suffix",
            ]
        }

        self.assertTrue(payload_examples._match_pattern(expected, "prefix---suffix"))
        self.assertFalse(payload_examples._match_pattern(expected, "prefix---suf"))

    def test_match_pattern_invalid_any_string_payload_fails_fast(self):
        expected = {payload_examples._ANY_STRING_TOKEN: "not-a-list-or-bool"}

        with self.assertRaisesRegex(
            AssertionError, r"invalid any-string token payload"
        ):
            payload_examples._match_pattern(expected, "abc")

    def test_verify_example_payload_searches_recursively(self):
        record = _make_record(
            claim_id="mp.plus.example.recursive",
            payload='{"tmpl_name": "מ:פסוק", "tmpl_params": {"1": "איוב"}}',
            subject="mp:plus",
        )
        ctx = _ctx(
            plus_files=[
                {
                    "book39s": [
                        {
                            "chapters": {
                                "1": {
                                    "1": [
                                        "text",
                                        {
                                            "nested": {
                                                "tmpl_name": "מ:פסוק",
                                                "tmpl_params": {"1": "איוב"},
                                            }
                                        },
                                    ]
                                }
                            }
                        }
                    ]
                }
            ]
        )

        payload_examples.verify_example_payload(record, ctx)

    def test_verify_example_payload_fails_when_not_found(self):
        record = _make_record(
            claim_id="mp.plus.example.not-found",
            payload='{"a": 999}',
            subject="mp:plus",
        )
        ctx = _ctx(plus_files=[{"a": 1}])

        with self.assertRaisesRegex(
            AssertionError, r"example payload pattern not found in corpus"
        ):
            payload_examples.verify_example_payload(record, ctx)

    def test_all_example_json_payload_strings_are_parseable(self):
        claims = mam_parsed_docs_build.collect_explicit_claims()

        failures = []
        for claim_id, record in claims.records_by_id.items():
            if ".example." not in claim_id:
                continue
            if not isinstance(record.payload, str):
                continue
            text = record.payload.strip()
            if not text.startswith("{") and not text.startswith("["):
                continue
            try:
                json.loads(text)
            except json.JSONDecodeError as exc:
                failures.append(f"{claim_id}: {exc}")

        self.assertEqual([], failures, msg="\n".join(failures))


if __name__ == "__main__":
    unittest.main()
